// Mulberry32: a tiny, fast 32-bit PRNG with good distribution for games.
// Deterministic given the same seed. NOT cryptographically secure.
export function mulberry32(seed: number): () => number {
  let a = seed | 0;
  if (a === 0) a = 0xdeadbeef;
  return function next(): number {
    a = (a + 0x6d2b79f5) | 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export type Rng = () => number;

export function makeRng(seed: number): Rng {
  return mulberry32(seed);
}

export function rngInt(rng: Rng, min: number, maxInclusive: number): number {
  return Math.floor(rng() * (maxInclusive - min + 1)) + min;
}

export function rngPick<T>(rng: Rng, arr: readonly T[]): T {
  if (arr.length === 0) throw new Error('rngPick on empty array');
  const idx = Math.floor(rng() * arr.length);
  // safe: arr is non-empty, idx < arr.length
  return arr[idx] as T;
}

export function rngWeighted<T>(rng: Rng, items: readonly T[], weights: readonly number[]): T {
  if (items.length !== weights.length) throw new Error('items/weights length mismatch');
  let total = 0;
  for (const w of weights) total += w;
  if (total <= 0) throw new Error('non-positive total weight');
  let pick = rng() * total;
  for (let i = 0; i < items.length; i++) {
    pick -= weights[i] as number;
    if (pick <= 0) return items[i] as T;
  }
  return items[items.length - 1] as T;
}

// Pure math + grid helpers. No engine code.

export const SQRT2 = Math.SQRT2;

export function clamp(x: number, lo: number, hi: number): number {
  return x < lo ? lo : x > hi ? hi : x;
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function dist2(ax: number, ay: number, bx: number, by: number): number {
  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

export function chebyshev(ax: number, ay: number, bx: number, by: number): number {
  return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
}

export function chebyshevRange(ax: number, ay: number, bx: number, by: number, range: number): boolean {
  return Math.abs(ax - bx) <= range && Math.abs(ay - by) <= range;
}

// Octile distance heuristic for 8-dir A* on uniform-cost tiles.
export function octile(dx: number, dy: number): number {
  const ax = Math.abs(dx);
  const ay = Math.abs(dy);
  const min = ax < ay ? ax : ay;
  const max = ax < ay ? ay : ax;
  return (max - min) + SQRT2 * min;
}

export interface Grid {
  width: number;
  height: number;
}

// In-bounds test.
export function inBounds(g: Grid, x: number, y: number): boolean {
  return x >= 0 && y >= 0 && x < g.width && y < g.height;
}

// Faction, tile, unit, building data tables. Everything is data-driven.

export type FactionId = 'human' | 'orc';

export interface FactionDef {
