      // neighbor must be in the set the center can have in direction d
      // the neighbor's "direction toward us" is the opposite
      const opp = Collapser.OPPOSITE[d] as number;
      // We need: tiles in neighbor mask that the center would accept in dir d
      // The center accepts in dir d anything allowed by any of its possible tiles' rules[d]
