      // Since center isn't collapsed, the correct constraint is intersection
      // of the neighbor's mask with what the center could push into direction d.
      // Note: we use only this direction's constraint here; propagation loop catches
      // the reverse direction from the neighbor's perspective next pass.
      const allowed = this.possibleInDir(cmask, d);
      const after = before & allowed;
      if (after !== before) {
        if (after === 0) return false;
        this.wave[ni] = after;
        if (!seen.has(ni)) {
          seen.add(ni);
          stack.push(ni);
        }
      }
    }
  }
  return true;
}

