it('AI builds barracks within 90s of game start (difficulty 1)', () => {
  const { w, ai } = bootWorld(1, 0, 1, 'human');
  const rng = mulberry32(7);
  // give the AI lots of resources so build order isn't blocked by money
  w.factions[ai].gold = 5000;
  w.factions[ai].wood = 5000;
  let elapsed = 0;
  let barracks = false;
  const dt = 1 / 60;
  const end = 60; // 1 minute (still well within typical AI build times)
  while (elapsed < end) {
    tick(w, dt, rng);
    aiTick(w, ai, 1, rng);
    elapsed += dt;
    if (Array.from(w.buildings.values()).some((b) => b.faction === ai && b.buildingKind === 'barracks')) {
      barracks = true;
      break;
    }
  }
  expect(barracks).toBe(true);
});

it('AI produces military units after barracks is built', () => {
  const { w, ai } = bootWorld(1, 0, 1, 'human');
  const rng = mulberry32(11);
  w.factions[ai].gold = 5000;
  w.factions[ai].wood = 5000;
  let elapsed = 0;
  let military = 0;
  const dt = 1 / 60;
  const end = 90; // 1.5 minutes — AI builds barracks + trains 2 units within this
  while (elapsed < end) {
    tick(w, dt, rng);
    aiTick(w, ai, 1, rng);
    elapsed += dt;
    military = 0;
    for (const u of w.units.values()) {
      if (u.faction === ai && (u.unitKind === 'melee' || u.unitKind === 'ranged' || u.unitKind === 'heavy')) military++;
    }
    if (military >= 2) break;
  }
  expect(military).toBeGreaterThanOrEqual(2);
});

