// Pick the cell with minimum entropy > 1.
private pickMinEntropy(): number {
  let bestIdx = -1;
  let bestEntropy = Infinity;
  for (let i = 0; i < this.wave.length; i++) {
    const m = this.wave[i] as number;
    const p = popcount(m);
    if (p <= 1) continue;
    // Shannon-like entropy: -sum p*log p, weighted by tile weights
    let e = 0;
    let total = 0;
    for (let b = 0; b < TILE_IDS.length; b++) {
      if (m & TILE_BIT(b)) {
        const w = TILES[TILE_IDS[b] as TileId].weight;
        total += w;
      }
    }
    if (total <= 0) continue;
    for (let b = 0; b < TILE_IDS.length; b++) {
      if (m & TILE_BIT(b)) {
        const w = TILES[TILE_IDS[b] as TileId].weight / total;
        e -= w * Math.log(w);
      }
    }
    // tiny deterministic tiebreak
    e += this.entropyNoise[i] as number * 1e-6;
    if (e < bestEntropy) {
      bestEntropy = e;
      bestIdx = i;
    }
  }
  return bestIdx;
}

