function isClear(map: MapData, x: number, y: number, radius: number): boolean {
  for (let dy = -radius; dy <= radius; dy++) {
    for (let dx = -radius; dx <= radius; dx++) {
      const tx = x + dx;
      const ty = y + dy;
      if (tx < 0 || ty < 0 || tx >= map.width || ty >= map.height) return false;
      const t = map.tiles[ty * map.width + tx] as TileId;
      const d = TILES[t];
      if (!d.buildable) return false;
    }
  }
  return true;
}

