content.text:
AI produces wood but no military, and the orc is stuck. The AI can't ever train a melee unit because melee costs 600g and the AI only has 300g (all carry is full, workers idle). To force the workers to keep harvesting gold, the AI should prioritize gold when gold is low.

Looking at the worker `decideWorkerAction`:
```ts
const needGold = harvestF.gold < 600;
const needWood = harvestF.wood < 400;
const order: ('gold' | 'wood')[] = needGold ? ['gold', 'wood'] : needWood ? ['wood', 'gold'] : ['gold', 'wood'];
```

`needGold = gold < 600` is true. So order = ['gold', 'wood']. nearestResource for gold returns null (too far). Then it tries wood. So workers keep chopping wood.

The fix: increase the search range for gold so workers can find farther gold mines:

edits.newText:
export function nearestResource(w: World, x: number, y: number, type: 'gold' | 'wood', maxR: number): ResourceTile | null {
  let best: ResourceTile | null = null;
  let bestD = Infinity;
  for (const r of w.resources) {
    if (r.type !== type || r.amount <= 0) continue;
    if (r.reservedBy !== undefined) continue; // someone is on the way / harvesting
    const d = dist2(r.x, r.y, x, y);
    if (d > maxR * maxR) continue;
    if (d < bestD) { bestD = d; best = r; }
  }
  return best;
}

export function nearestResourceUnreserved(w: World, x: number, y: number, type: 'gold' | 'wood', maxR: number): ResourceTile | null {
  // same as nearestResource, but doesn't require reservedBy === undefined
  let best: ResourceTile | null = null;
  let bestD = Infinity;
  for (const r of w.resources) {
    if (r.type !== type || r.amount <= 0) continue;
    const d = dist2(r.x, r.y, x, y);
    if (d > maxR * maxR) continue;
    if (d < bestD) { bestD = d; best = r; }
  }
  return best;
}

